  AS r(s text, k text, f text, v text, p int, m text, mo text, g text, t text)
JOIN "_cat_fam" fa ON fa.f = r.f;

-- La configuration « équipement non précisé » de chaque génération.
DROP TABLE IF EXISTS "_cat_conf";
CREATE TEMPORARY TABLE "_cat_conf" AS
SELECT DISTINCT ON (r.m, r.g) r.m, r.g, c."id" AS conf
FROM (SELECT DISTINCT m, mo, g FROM "_cat_rec") r
JOIN "VehicleMake" mk ON mk."slug" = r.m
JOIN "VehicleModel" mo ON mo."makeId" = mk."id" AND mo."slug" = r.mo
JOIN "VehicleGeneration" ge ON ge."modelId" = mo."id" AND ge."slug" = r.g
JOIN "VehicleConfiguration" c ON c."generationId" = ge."id"
JOIN "LightingEquipment" e ON e."id" = c."equipmentId"
ORDER BY r.m, r.g, (e."code" = 'NON_PRECISE') DESC, c."id";

-- Seules les fiches dont le véhicule est trouvé.
DELETE FROM "_cat_rec" r WHERE NOT EXISTS (SELECT 1 FROM "_cat_conf" c WHERE c.m = r.m AND c.g = r.g);

INSERT INTO "Product" ("id", "slug", "name", "tagline", "description", "body", "status", "vehicleType", "publishedAt", "createdAt", "updatedAt")
SELECT
  'cat' || substr(md5('p:' || r.s), 1, 22),
  r.s,
  replace(r.nom, '{v}', r.v),
  replace(r.tag, '{v}', r.v),
  replace(r.quoi, '{v}', r.v),
  replace(r.corps, '{v}', r.v),
  'PUBLISHED'::"ProductStatus",
  r.t::"VehicleType",
  NOW(), NOW(), NOW()
FROM "_cat_rec" r
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "ProductVariant" ("id", "productId", "sku", "name", "packaging", "priceCents", "vatRateId", "stockOnHand", "createdAt", "updatedAt")
SELECT
  'cav' || substr(md5('v:' || r.k), 1, 22),
  p."id",
  r.k,
  p."name",
  'KIT'::"Packaging",
  r.p,
  (SELECT "id" FROM "VatRate" WHERE "code" = 'FR_STANDARD'),
  1,
  NOW(), NOW()
FROM "_cat_rec" r
JOIN "Product" p ON p."slug" = r.s AND p."id" = 'cat' || substr(md5('p:' || r.s), 1, 22)
ON CONFLICT ("sku") DO NOTHING;

INSERT INTO "StockMovement" ("id", "variantId", "delta", "reason", "reference", "createdAt")
SELECT 'cam' || substr(md5('m:' || r.k), 1, 22), v."id", 1, 'import', 'catalogue:ledperf', NOW()
FROM "_cat_rec" r
JOIN "ProductVariant" v ON v."sku" = r.k AND v."id" = 'cav' || substr(md5('v:' || r.k), 1, 22)
ON CONFLICT ("id") DO NOTHING;

INSERT INTO "Fitment" ("id", "configurationId", "positionId", "variantId", "status", "quantity", "createdAt", "updatedAt")
SELECT 'caf' || substr(md5('f:' || r.k), 1, 22), c.conf, lp."id", v."id", 'CONFIRMED'::"FitmentStatus", 1, NOW(), NOW()
FROM "_cat_rec" r
JOIN "_cat_conf" c ON c.m = r.m AND c.g = r.g
JOIN "LightPosition" lp ON lp."code" = r.pos
JOIN "ProductVariant" v ON v."sku" = r.k AND v."id" = 'cav' || substr(md5('v:' || r.k), 1, 22)
ON CONFLICT DO NOTHING;

INSERT INTO "ProductCategory" ("productId", "categoryId", "position")
SELECT p."id", cat."id", 0
FROM "_cat_rec" r
JOIN "Product" p ON p."slug" = r.s AND p."id" = 'cat' || substr(md5('p:' || r.s), 1, 22)
JOIN "Category" cat ON cat."slug" = r.cat
ON CONFLICT DO NOTHING;

-- Modules de plaque : le nom dit ce que c'est.
UPDATE "Product" p
SET
  "name" = 'Modules LED de plaque pour ' || substring(p."name" from ' pour (.+)$'),
  "updatedAt" = NOW()
WHERE p."name" LIKE 'Pack LED éclairage de plaque pour %'
  AND EXISTS (
    SELECT 1 FROM "ProductCategory" pc JOIN "Category" c ON c."id" = pc."categoryId"
    WHERE pc."productId" = p."id" AND c."slug" = 'modules-plaque'
  );

UPDATE "ProductVariant" v
SET "name" = p."name", "updatedAt" = NOW()
FROM "Product" p
WHERE v."productId" = p."id" AND p."name" LIKE 'Modules LED de plaque pour %' AND v."name" <> p."name";

DROP TABLE IF EXISTS "_cat_rec";
DROP TABLE IF EXISTS "_cat_conf";
DROP TABLE IF EXISTS "_cat_fam";
